class ImageClassifier(nn.Module):

    def __init__(self) -> None:
        super().__init__()
        self.features = nn.Sequential(nn.Conv2d(5, 24, kernel_size=3, padding=1, bias=False), nn.BatchNorm2d(24), nn.GELU(), MixedPool2d(), nn.Conv2d(24, 48, kernel_size=3, padding=1, bias=False), nn.BatchNorm2d(48), nn.GELU(), MixedPool2d(), nn.Conv2d(48, 80, kernel_size=3, padding=1, bias=False), nn.BatchNorm2d(80), nn.GELU())
        self.refine = nn.Sequential(nn.Conv2d(80, 80, kernel_size=3, padding=1, groups=80, bias=False), nn.BatchNorm2d(80), nn.GELU(), nn.Conv2d(80, 80, kernel_size=1, bias=False), nn.BatchNorm2d(80))
        self.aggregate_local = nn.Sequential(nn.Conv2d(80, 40, kernel_size=3, stride=2, padding=1, bias=False), nn.BatchNorm2d(40), nn.GELU())
        self.aggregate_context = nn.Sequential(nn.Conv2d(80, 24, kernel_size=3, stride=2, padding=2, dilation=2, bias=False), nn.BatchNorm2d(24), nn.GELU())
        self.classifier = nn.Sequential(nn.Flatten(), nn.Linear(64 * 4 * 4, 140), nn.LayerNorm(140), nn.GELU(), nn.Dropout(0.1), nn.Linear(140, 10))

    @staticmethod
    def _image_basis(images: torch.Tensor) -> torch.Tensor:
        padded = F.pad(images, (1, 1, 1, 1), mode='replicate')
        local_mean = F.avg_pool2d(padded, kernel_size=3, stride=1)
        local_contrast = images - local_mean
        gradient_x = 0.125 * (padded[:, :, :-2, 2:] + 2.0 * padded[:, :, 1:-1, 2:] + padded[:, :, 2:, 2:] - padded[:, :, :-2, :-2] - 2.0 * padded[:, :, 1:-1, :-2] - padded[:, :, 2:, :-2])
        gradient_y = 0.125 * (padded[:, :, 2:, :-2] + 2.0 * padded[:, :, 2:, 1:-1] + padded[:, :, 2:, 2:] - padded[:, :, :-2, :-2] - 2.0 * padded[:, :, :-2, 1:-1] - padded[:, :, :-2, 2:])
        edge_energy = torch.sqrt(gradient_x.square() + gradient_y.square() + 1e-06)
        return torch.cat((images, local_contrast, gradient_x, gradient_y, edge_energy), dim=1)

    def _forward_once(self, images: torch.Tensor) -> torch.Tensor:
        features = self.features(self._image_basis(images))
        features = F.gelu(features + self.refine(features))
        features = torch.cat((self.aggregate_local(features), self.aggregate_context(features)), dim=1)
        return self.classifier(features)

    def _flip_average(self, images: torch.Tensor) -> torch.Tensor:
        return 0.5 * (self._forward_once(images) + self._forward_once(images.flip(-1)))

    def forward(self, images: torch.Tensor) -> torch.Tensor:
        if self.training:
            return self._forward_once(images)
        height, width = images.shape[-2:]
        padded = F.pad(images, (2, 2, 2, 2), mode='replicate')
        logits = 0.36 * self._flip_average(images)
        for delta_y in range(-2, 3):
            for delta_x in range(-2, 3):
                if delta_y == 0 and delta_x == 0:
                    continue
                shifted = padded[:, :, 2 + delta_y:2 + delta_y + height, 2 + delta_x:2 + delta_x + width]
                radius = max(abs(delta_y), abs(delta_x))
                if radius == 1:
                    if delta_x == 0:
                        weight = 0.1
                    elif delta_y == 0:
                        weight = 0.08
                    else:
                        weight = 0.045
                else:
                    manhattan_distance = abs(delta_y) + abs(delta_x)
                    if manhattan_distance == 2:
                        weight = 0.009375
                    elif manhattan_distance == 3:
                        weight = 0.00625
                    else:
                        weight = 0.003125
                logits = logits + weight * self._flip_average(shifted)
        return 1.253 * logits

