class ImageClassifier(nn.Module):

    def __init__(self) -> None:
        super().__init__()
        axis = torch.linspace(-1.0, 1.0, 28)
        vertical_position = axis[:, None].expand(28, 28)
        horizontal_radius = axis.abs()[None, :].expand(28, 28)
        self.register_buffer('coordinate_channels', torch.stack((vertical_position, horizontal_radius)).unsqueeze(0), persistent=False)
        self.features = nn.Sequential(nn.Conv2d(3, 32, kernel_size=3, padding=1, bias=False), nn.BatchNorm2d(32), nn.GELU(), ResidualBlock(32, 32), nn.MaxPool2d(2), ResidualBlock(32, 64), nn.MaxPool2d(2), ResidualBlock(64, 64))
        self.classifier = nn.Sequential(nn.Flatten(), nn.Linear(64 * 7 * 7, 30), nn.GELU(), nn.Dropout(0.1), nn.Linear(30, 10))

    def _forward_once(self, images: torch.Tensor) -> torch.Tensor:
        coordinates = self.coordinate_channels.expand(images.shape[0], -1, -1, -1)
        positioned_images = torch.cat((images, coordinates), dim=1)
        return self.classifier(self.features(positioned_images))

    def forward(self, images: torch.Tensor) -> torch.Tensor:
        if self.training:
            return self._forward_once(images)
        padded = F.pad(images, (1, 1, 1, 1), mode='replicate')
        views = (images, padded[:, :, 0:28, 1:29], padded[:, :, 2:30, 1:29], padded[:, :, 1:29, 0:28], padded[:, :, 1:29, 2:30])
        probabilities = 2.0 * F.softmax(self._forward_once(views[0]), dim=1)
        probabilities = probabilities + 2.0 * F.softmax(self._forward_once(views[0].flip(-1)), dim=1)
        for view in views[1:]:
            probabilities = probabilities + F.softmax(self._forward_once(view), dim=1)
            probabilities = probabilities + F.softmax(self._forward_once(view.flip(-1)), dim=1)
        probabilities = probabilities / (2.0 * (len(views) + 1))
        return probabilities.clamp_min(1e-08).log()

