        self._ema_parameter_names: list[str] = []
        self._ema_buffer_names: list[str] = []
        for index, (name, parameter) in enumerate(self.named_parameters()):
            buffer_name = f'_ema_parameter_{index}'
            self.register_buffer(buffer_name, parameter.detach().clone(), persistent=False)
            self._ema_parameter_names.append(name)
            self._ema_buffer_names.append(buffer_name)

    @torch.no_grad()
    def update_ema(self) -> None:
        for buffer_name, parameter in zip(self._ema_buffer_names, self.parameters()):
            getattr(self, buffer_name).lerp_(parameter, 0.02)

    def _forward_once(self, images: torch.Tensor, parameters: dict[str, torch.Tensor] | None=None) -> torch.Tensor:
        if parameters is None:
            return self.classifier(self.features(images))
        feature_parameters = {name.split('.', 1)[1]: value for name, value in parameters.items() if name.startswith('features.')}
        classifier_parameters = {name.split('.', 1)[1]: value for name, value in parameters.items() if name.startswith('classifier.')}
        features = torch.func.functional_call(self.features, feature_parameters, (images,))
        return torch.func.functional_call(self.classifier, classifier_parameters, (features,))

    def forward(self, images: torch.Tensor) -> torch.Tensor:
        parameters = None
        if not self.training:
            parameters = {name: getattr(self, buffer_name) for name, buffer_name in zip(self._ema_parameter_names, self._ema_buffer_names)}
        logits = self._forward_once(images, parameters)
        if not self.training:
            flipped_logits = self._forward_once(torch.flip(images, dims=(-1,)), parameters)
            logits = 0.5 * (logits + flipped_logits)
        return logits

