class ChannelAttention(nn.Module):

    def __init__(self) -> None:
        super().__init__()
        self.projection = nn.Sequential(nn.Linear(64, 32), nn.SiLU(), nn.Linear(32, 64))
        nn.init.zeros_(self.projection[-1].weight)
        nn.init.zeros_(self.projection[-1].bias)

    def forward(self, features: torch.Tensor) -> torch.Tensor:
        gates = self.projection(features.mean(dim=(2, 3)))
        return features * (2.0 * torch.sigmoid(gates))[:, :, None, None]

