class ImageClassifier(nn.Module):

    def __init__(self) -> None:
        super().__init__()
        self.features = nn.Sequential(nn.Conv2d(1, 32, kernel_size=3, padding=1, bias=False), nn.BatchNorm2d(32), nn.SiLU(), nn.Conv2d(32, 32, kernel_size=3, padding=1, bias=False), nn.BatchNorm2d(32), nn.SiLU(), nn.MaxPool2d(2), nn.Conv2d(32, 64, kernel_size=3, padding=1, bias=False), nn.BatchNorm2d(64), nn.SiLU(), nn.Conv2d(64, 64, kernel_size=3, padding=1, bias=False), nn.BatchNorm2d(64), nn.SiLU(), nn.MaxPool2d(2), ResidualRefinement(), ResidualRefinement(), ChannelAttention(), SpatialAttention())
        self.classifier = nn.Sequential(nn.Flatten(), nn.Linear(64 * 7 * 7, 54), nn.SiLU(), nn.Linear(54, 10))

    def forward(self, images: torch.Tensor) -> torch.Tensor:
        logits = self.classifier(self.features(images))
        if self.training:
            return logits
        padded = F.pad(images, (1, 1, 1, 1), mode='replicate')
        views = (images, padded[:, :, 0:28, 0:28], padded[:, :, 0:28, 1:29], padded[:, :, 0:28, 2:30], padded[:, :, 1:29, 0:28], padded[:, :, 1:29, 2:30], padded[:, :, 2:30, 0:28], padded[:, :, 2:30, 1:29], padded[:, :, 2:30, 2:30])
        view_weights = (36.0, 1.0, 6.0, 1.0, 6.0, 6.0, 1.0, 6.0, 1.0)
        log_probs = []
        for view, weight in zip(views, view_weights):
            log_weight = math.log(weight)
            log_probs.append(F.log_softmax(self.classifier(self.features(view)), dim=1) + log_weight)
            log_probs.append(F.log_softmax(self.classifier(self.features(view.flip(-1))), dim=1) + log_weight)
        return torch.logsumexp(torch.stack(log_probs), dim=0) - math.log(2.0 * sum(view_weights))

program_parts.ResidualRefinement:
class ResidualRefinement(nn.Module):

    def __init__(self) -> None:
        super().__init__()
        self.branch = nn.Sequential(nn.Conv2d(64, 64, kernel_size=3, padding=1, groups=64, bias=False), nn.BatchNorm2d(64), nn.SiLU(), nn.Conv2d(64, 64, kernel_size=1, bias=False), nn.BatchNorm2d(64))
        nn.init.zeros_(self.branch[-1].weight)

    def forward(self, features: torch.Tensor) -> torch.Tensor:
        return features + self.branch(features)

program_parts.SpatialAttention:
class SpatialAttention(nn.Module):

    def __init__(self) -> None:
        super().__init__()
        self.projection = nn.Conv2d(2, 1, kernel_size=7, padding=3)
        nn.init.zeros_(self.projection.weight)
        nn.init.zeros_(self.projection.bias)

    def forward(self, features: torch.Tensor) -> torch.Tensor:
        descriptors = torch.cat((features.mean(dim=1, keepdim=True), features.amax(dim=1, keepdim=True)), dim=1)
        gates = self.projection(descriptors)
        return features * (2.0 * torch.sigmoid(gates))

