class ImageClassifier(nn.Module):

    def __init__(self) -> None:
        super().__init__()
        self.features = nn.Sequential(nn.Conv2d(1, 32, kernel_size=3, padding=1, bias=False), nn.BatchNorm2d(32), nn.GELU(), nn.Conv2d(32, 32, kernel_size=3, padding=1, bias=False), nn.BatchNorm2d(32), nn.GELU(), nn.MaxPool2d(2), nn.Conv2d(32, 64, kernel_size=3, padding=1, bias=False), nn.BatchNorm2d(64), nn.GELU(), nn.Conv2d(64, 64, kernel_size=3, padding=1, bias=False), nn.BatchNorm2d(64), nn.GELU(), nn.MaxPool2d(2), nn.Conv2d(64, 64, kernel_size=3, padding=2, dilation=2, bias=False), nn.BatchNorm2d(64), nn.GELU())
        self.channel_gate = nn.Sequential(nn.AdaptiveAvgPool2d(1), nn.Flatten(), nn.Linear(64, 16), nn.GELU(), nn.Linear(16, 64), nn.Sigmoid())
        self.classifier = nn.Sequential(nn.Flatten(), nn.Linear(64 * 7 * 7, 46), nn.GELU(), nn.Dropout(0.15), nn.Linear(46, 10))

    def _forward_once(self, images: torch.Tensor) -> torch.Tensor:
        features = self.features(images)
        channel_scale = 2.0 * self.channel_gate(features)
        features = features * channel_scale[:, :, None, None]
        return self.classifier(features)

    def forward(self, images: torch.Tensor) -> torch.Tensor:
        logits = self._forward_once(images)
        if not self.training:
            flipped_logits = self._forward_once(torch.flip(images, dims=(3,)))
            logits = 0.5 * (logits + flipped_logits)
        return logits
